120	            policy.classify(99, |token_id| token_id == 99),
121	            Some(StopCause::Eos(99))
122	        );
123	    }
124	
125	    #[test]
126	    fn primary_eos_keeps_secondary_model_eos_as_token_stop() {
127	        let policy = StopPolicy::new(EosPolicy::Token(1), vec![1, 2]);
128	
129	        assert_eq!(policy.classify(1, |_| true), Some(StopCause::Eos(1)));
130	        assert_eq!(policy.classify(2, |_| true), Some(StopCause::Token(2)));
131	        assert_eq!(policy.classify(3, |_| true), None);
132	    }
133	}
