421	    fn admission_tokens_and_finish_fold_into_one_entry() {
422	        let (handle, mut backend) = scheduler_pair();
423	        let _control = handle.submit(request(vec![1, 2, 3]));
424	        let envelope = backend.submissions.try_recv().expect("envelope");
425	        let id = backend.ledger.register(envelope).id;
