442	        assert_eq!(update.tokens, vec![10, 11]);
443	        assert_eq!(update.logprobs.len(), 2);
444	        assert_eq!(update.cached_tokens, Some(2));
445	        assert!(matches!(
446	            update.terminal,
447	            Some(Terminal::Finished {
448	                reason: FinishReason::Stop,
449	                stop_cause: Some(StopCause::Token(11)),
