553	        let step = steps.try_recv().expect("write-off message");
554	        let mut prompts: Vec<usize> = step
555	            .updates
556	            .iter()
557	            .map(|update| match update.terminal {
558	                Some(Terminal::Failed { prompt_tokens, .. }) => prompt_tokens,
559	                ref other => panic!("write-off must be Failed, got {other:?}"),
560	            })
561	            .collect();
562	        prompts.sort_unstable();
563	        assert_eq!(prompts, vec![1, 2]);
564	    }
