43	/// Spawn one scheduler: mint the wiring, start the driver thread, return the
44	/// frontend end. `name` names the OS thread (shows in `top`/gdb).
45	pub fn spawn_scheduler<S: Scheduler + 'static>(name: &str, scheduler: S) -> LiveScheduler {
46	    let (handle, backend) = scheduler_pair();
47	    let join = std::thread::Builder::new()
48	        .name(name.to_string())
49	        .spawn(move || drive(scheduler, backend))
50	        .expect("failed to spawn scheduler thread");
51	    LiveScheduler { handle, join }
52	}
