73	pub(crate) struct SteppedEngineBridge {
74	    pub(crate) input_address: String,
75	    pub(crate) output_address: String,
76	    pub(crate) scheduler: SchedulerHandle,
77	    pub(crate) kv_capacity: Option<KvCapacity>,
78	    pub(crate) max_model_len: u32,
79	    pub(crate) engine_index: u32,
80	    pub(crate) data_parallel_size: u32,
81	}
82	
83	impl SteppedEngineBridge {
84	    pub(crate) async fn run(mut self, shutdown: CancellationToken) -> Result<()> {
85	        let engine_dead = CancellationToken::new();
86	        let mut steps = self
87	            .scheduler
88	            .take_steps()
89	            .context("partition step stream already taken")?;
90	        let mut tracker = StatsTracker::default();
91	        let Some(BridgeLink {
92	            mut input,
93	            output_tx,
94	            mut child_tasks,
95	        }) = connect_link(
96	            &self.input_address,
97	            &self.output_address,
98	            self.engine_index,
99	            self.data_parallel_size,
100	            self.max_model_len,
101	            self.kv_capacity,
102	            None,
103	            Some(engine_dead.clone()),
104	            &shutdown,
105	        )
106	        .await?
107	        else {
108	            return Ok(());
109	        };
110	        send_outputs(
111	            &output_tx,
112	            RequestBatchOutputs {
113	                engine_index: self.engine_index,
114	                scheduler_stats: Some(Box::new(self.stats(&mut tracker))),
115	                timestamp: now_secs_f64(),
116	                ..Default::default()
117	            }
118	            .into(),
119	        )?;
120	
121	        let anchor = UnixAnchor::now();
122	        let mut streams: HashMap<RequestId, SteppedStream> = HashMap::new();
123	        let mut names: HashMap<String, RequestId> = HashMap::new();
124	
125	        info!(
126	            "local vLLM engine {} stepped bridge connected: input={}, output={}, max_model_len={}",
127	            self.engine_index, self.input_address, self.output_address, self.max_model_len
128	        );
129	
130	        let run_result = loop {
131	            tokio::select! {
132	                biased;
133	                () = shutdown.cancelled() => break Ok(()),
134	                joined = child_tasks.join_next(), if !child_tasks.is_empty() => {
135	                    if shutdown.is_cancelled() {
136	                        break Ok(());
137	                    }
138	                    break match joined {
139	                        Some(Ok((name, Ok(())))) => {
140	                            Err(anyhow::anyhow!("local engine {name} exited unexpectedly"))
141	                        }
142	                        Some(Ok((name, Err(error)))) => {
143	                            Err(error).with_context(|| format!("local engine {name} failed"))
144	                        }
145	                        Some(Err(error)) => {
146	                            Err(anyhow::anyhow!("local engine child task panicked: {error}"))
147	                        }
148	                        None => Err(anyhow::anyhow!("local engine child task set became empty")),
149	                    };
150	                }
151	                Some(step) = steps.recv() => {
152	                    if let Err(error) = self.dispatch_step(
153	                        step,
154	                        &anchor,
155	                        &mut streams,
156	                        &mut names,
157	                        &mut tracker,
158	                        &output_tx,
159	                    ) {
160	                        break Err(error).context("failed to dispatch local engine step");
161	                    }
162	                }
163	                () = self.scheduler.exited() => {
164	                    // Dispatch what the driver committed before it exited first.
165	                    if !steps.is_empty() {
166	                        continue;
167	                    }
168	                    break Err(anyhow::anyhow!("scheduler exited"));
169	                }
170	                recv = input.recv() => {
171	                    let message = match recv.context("failed to receive local engine request") {
172	                        Ok(message) => message,
173	                        Err(error) => break Err(error),
174	                    };
175	                    if let Err(error) = self.handle_message(
176	                        message,
177	                        &mut streams,
178	                        &mut names,
179	                        &output_tx,
180	                    ) {
181	                        break Err(error).context("failed to handle local engine request");
182	                    }
183	                }
184	            }
185	        };
186	
187	        // Flip every in-flight request's abort flag so the scheduler retires
188	        // them on its next touch; dropping the partition handle afterwards
189	        // disconnects the submission channel and lets the driver drain out.
190	        for state in streams.values() {
191	            state.control.abort();
192	        }
193	        if run_result.is_err() {
194	            engine_dead.cancel();
195	        }
196	        drop(output_tx);
197	        // Deliver what is already queued, and after a failure the dead engine
198	        // notice, before stopping the link.
199	        if tokio::time::timeout(OUTPUT_DRAIN_TIMEOUT, async {
200	            while child_tasks.join_next().await.is_some() {}
201	        })
202	        .await
203	        .is_err()
204	        {
205	            warn!(
206	                "local engine {} output did not drain in time",
207	                self.engine_index
208	            );
209	        }
210	        child_tasks.abort_all();
211	        while child_tasks.join_next().await.is_some() {}
212	
213	        run_result
214	    }
215	
216	    /// Stats for an outgoing batch; the counter deltas run from the last
217	    /// batch stamped, not the last step run.
218	    fn stats(&self, tracker: &mut StatsTracker) -> SchedulerStats {
219	        tracker.stats(&self.scheduler.metrics())
220	    }
221	
222	    fn dispatch_step(
223	        &self,
224	        step: StepOutputs,
225	        anchor: &UnixAnchor,
226	        streams: &mut HashMap<RequestId, SteppedStream>,
227	        names: &mut HashMap<String, RequestId>,
228	        tracker: &mut StatsTracker,
229	        output_tx: &tokio::sync::mpsc::UnboundedSender<
230	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
231	        >,
232	    ) -> Result<()> {
233	        let mut outputs: Vec<EngineCoreOutput> = Vec::with_capacity(step.updates.len());
234	        let mut finished_requests: BTreeSet<String> = BTreeSet::new();
235	        for update in step.updates {
236	            // No stream entry means the request was aborted or already
237	            // finished; late updates (including retire-window drop bombs) are
238	            // dropped.
239	            let Some(state) = streams.get_mut(&update.id) else {
240	                continue;
241	            };
242	            let id = update.id;
243	            let (output, terminated) = reduce_update(state, update, anchor);
244	            if let Some(output) = output {
245	                outputs.push(output);
246	            }
247	            if terminated {
248	                // Dropping the state ends the root span, closing the trace.
249	                let state = streams.remove(&id).expect("terminated stream present");
250	                names.remove(&state.request_id);
251	                finished_requests.insert(state.request_id);
252	            }
253	        }
254	
255	        send_outputs(
256	            output_tx,
257	            RequestBatchOutputs {
258	                engine_index: self.engine_index,
259	                outputs,
260	                finished_requests: (!finished_requests.is_empty()).then_some(finished_requests),
261	                scheduler_stats: Some(Box::new(self.stats(tracker))),
262	                timestamp: now_secs_f64(),
263	                weight_version: None,
264	            }
265	            .into(),
266	        )
267	    }
268	
269	    fn handle_message(
270	        &self,
271	        message: ZmqMessage,
272	        streams: &mut HashMap<RequestId, SteppedStream>,
273	        names: &mut HashMap<String, RequestId>,
274	        output_tx: &tokio::sync::mpsc::UnboundedSender<
275	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
276	        >,
277	    ) -> Result<()> {
278	        let frames = message.into_vec();
279	        if frames.len() != 2 {
280	            bail!(
281	                "expected 2 local engine request frames, got {}",
282	                frames.len()
283	            );
284	        }
285	
286	        match frames[0].as_ref() {
287	            ty if ty == EngineCoreRequestType::Add.to_frame().as_ref() => {
288	                let request: EngineCoreRequest =
289	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
290	                self.start_request(request, streams, names, output_tx)
291	            }
292	            ty if ty == EngineCoreRequestType::Abort.to_frame().as_ref() => {
293	                let request_ids: Vec<String> =
294	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
295	                for request_id in request_ids {
296	                    // Drop our state first, then flip the abort flag (whose
297	                    // `Release` store orders after the removal); the
298	                    // scheduler's next touch retires the request, and any
299	                    // update already in flight finds no stream entry.
300	                    let Some(id) = names.remove(&request_id) else {
301	                        continue;
302	                    };
303	                    if let Some(state) = streams.remove(&id) {
304	                        state.control.abort();
305	                    }
306	                }
307	                Ok(())
308	            }
309	            ty if ty == EngineCoreRequestType::Utility.to_frame().as_ref() => {
310	                let (_client_index, call_id, method_name, _args): (
311	                    u32,
312	                    UtilityCallId,
313	                    String,
314	                    rmpv::Value,
315	                ) = rmp_serde::from_slice(&frames[1])?;
316	                send_utility_response(self.engine_index, output_tx, call_id, &method_name)
317	            }
318	            other => bail!("unsupported local engine request type frame: {other:?}"),
319	        }
320	    }
