322	    fn start_request(
323	        &self,
324	        request: EngineCoreRequest,
325	        streams: &mut HashMap<RequestId, SteppedStream>,
326	        names: &mut HashMap<String, RequestId>,
327	        output_tx: &tokio::sync::mpsc::UnboundedSender<
328	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
329	        >,
330	    ) -> Result<()> {
331	        let EngineCoreRequest {
332	            request_id,
333	            prompt_token_ids,
334	            sampling_params,
335	            ..
336	        } = request;
337	        let Some(prompt_tokens) = prompt_token_ids else {
338	            warn!("request {request_id} dropped: missing prompt_token_ids");
339	            return send_terminal_output(
340	                self.engine_index,
341	                output_tx,
342	                request_id,
343	                EngineCoreFinishReason::Error,
344	                None,
345	                None,
346	                None,
347	            );
348	        };
349	        let Some(sampling_params) = sampling_params else {
350	            warn!("request {request_id} dropped: missing sampling_params");
351	            return send_terminal_output(
352	                self.engine_index,
353	                output_tx,
354	                request_id,
355	                EngineCoreFinishReason::Error,
356	                None,
357	                None,
358	                None,
359	            );
360	        };
361	
362	        if let Some(unsupported) = crate::vllm::wire::unsupported_request_params(&sampling_params) {
363	            warn!("request {request_id} rejected: {unsupported}");
364	            return send_terminal_output(
365	                self.engine_index,
366	                output_tx,
367	                request_id,
368	                EngineCoreFinishReason::Error,
369	                None,
370	                None,
371	                None,
372	            );
373	        }
374	
375	        let lora_adapter = match lora_adapter_from_sampling_params(&sampling_params) {
376	            Ok(adapter) => adapter,
377	            Err(error) => {
378	                let message = error.to_string();
379	                warn!("request {request_id} rejected: {message}");
380	                return send_terminal_output(
381	                    self.engine_index,
382	                    output_tx,
383	                    request_id,
384	                    EngineCoreFinishReason::Error,
385	                    Some(StopReason::Text(message)),
386	                    None,
387	                    None,
388	                );
389	            }
390	        };
391	        let extra_arg = |key: &str| {
392	            sampling_params
393	                .extra_args
394	                .as_ref()
395	                .and_then(|args| args.get(key))
396	        };
397	        let kv_transfer_params = extra_arg("kv_transfer_params").cloned();
398	        // The chat layer measured the generation prompt's token count at the
399	        // tail of a prompt only it saw as text; a count the prompt cannot hold
400	        // is no boundary.
401	        let history_tokens = extra_arg(GENERATION_PROMPT_TOKENS)
402	            .and_then(serde_json::Value::as_u64)
403	            .and_then(|tail| prompt_tokens.len().checked_sub(tail as usize));
404	        // The earlier turns' ends the chat layer measured, kept where they
405	        // fall inside this turn's history.
406	        let history_marks: Vec<usize> = extra_arg(HISTORY_MARKS)
407	            .and_then(serde_json::Value::as_array)
408	            .map(|marks| {
409	                marks
410	                    .iter()
411	                    .filter_map(serde_json::Value::as_u64)
412	                    .map(|m| m as usize)
413	                    .filter(|&m| m > 0 && history_tokens.is_some_and(|h| m < h))
414	                    .collect()
415	            })
416	            .unwrap_or_default();
417	        // Older stepped model producers still suppress their terminal token
418	        // and report only `FinishReason::Stop`. Keep the legacy sentinel for
419	        // that producer shape; typed stop causes carry the real token and do
420	        // not need a synthetic suffix.
421	        let stop_sentinel_id = stop_sentinel_id(
422	            sampling_params.eos_token_id,
423	            &sampling_params.stop_token_ids,
424	        );
425	
426	        // Open the request's root span before submit so its context travels
427	        // into the scheduler as the parent of the queue/prefill/decode spans;
428	        // noop (no allocation, `from_span` yields `None`) when tracing is off.
429	        let trace_root = if crate::tracing_state::is_enabled() {
430	            Span::root("request", SpanContext::random())
431	                .with_property(|| ("request_id", request_id.clone()))
432	        } else {
433	            Span::noop()
434	        };
435	        let trace_parent = SpanContext::from_span(&trace_root);
436	
437	        let control = self.scheduler.submit(Request {
438	            prompt_tokens,
439	            // Keep the legacy SamplingParams lowering unchanged for stepped
440	            // producers that have not migrated to StopPolicy. Qwen3 uses the
441	            // independent policy below for stop classification.
442	            params: convert_sampling(&sampling_params),
443	            history_tokens,
444	            history_marks,
445	            stop_policy: convert_stop_policy(&sampling_params),
446	            max_tokens: sampling_params.max_tokens as usize,
447	            lora_adapter,
448	            kv_transfer_params,
449	            logprobs: requested_logprobs(&sampling_params),
450	            prompt_logprobs: requested_prompt_logprobs(&sampling_params),
451	            trace_parent,
452	            client_label: Some(Arc::from(request_id.as_str())),
453	        });
454	
455	        names.insert(request_id.clone(), control.id());
456	        streams.insert(
457	            control.id(),
458	            SteppedStream::new(request_id, control, trace_root, stop_sentinel_id),
459	        );
460	        Ok(())
461	    }
462	}
