464	/// Per-request demux state, keyed by the contract's [`RequestId`]; `names`
465	/// maps the vLLM wire's string request id back to it for aborts.
466	struct SteppedStream {
467	    request_id: String,
468	    control: RequestControl,
469	    /// Queued/Scheduled wire events, held until the request's first shipped
470	    /// output (a scheduled-only update produces no request output).
471	    first_token_events: Option<Vec<EngineCoreEvent>>,
472	    /// Set by `Scheduled`; a request refused or failed while still queued
473	    /// never prefilled and reports no prefill stats.
474	    prompt_tokens: Option<usize>,
475	    cached_tokens: usize,
476	    prefill_stats_sent: bool,
477	    /// P/D handoff metadata can arrive in an update with no token or
478	    /// terminal, so retain it until the next output carries it to the router.
479	    kv_transfer_params: Option<serde_json::Value>,
480	    /// Compatibility sentinel for stepped producers that predate typed
481	    /// [`StopCause`]. New producers must include their triggering token in the
482	    /// update and therefore bypass this fallback.
483	    stop_sentinel_id: Option<u32>,
484	    /// Request-lifetime root span; held only for its `Drop`, which closes the
485	    /// trace when the stream state is removed.
486	    #[allow(dead_code)]
487	    trace_root: Span,
488	}
489	
490	impl SteppedStream {
491	    fn new(
492	        request_id: String,
493	        control: RequestControl,
494	        trace_root: Span,
495	        stop_sentinel_id: Option<u32>,
496	    ) -> Self {
497	        Self {
498	            request_id,
499	            control,
500	            first_token_events: None,
501	            prompt_tokens: None,
502	            cached_tokens: 0,
503	            prefill_stats_sent: false,
504	            kv_transfer_params: None,
505	            stop_sentinel_id,
506	            trace_root,
507	        }
508	    }
509	
510	    fn fail_prompt(&mut self, error: &anyhow::Error) -> (Option<EngineCoreOutput>, bool) {
511	        warn!("request {} failed: {error:#}", self.request_id);
512	        self.control.abort();
513	        let output = engine_output(
514	            self.request_id.clone(),
515	            Vec::new(),
516	            None,
517	            Some(EngineCoreFinishReason::Error),
518	            Some(StopReason::Text(error.to_string())),
519	            self.first_token_events.take(),
520	            self.take_prefill_stats(),
521	        );
522	        (Some(output), true)
523	    }
524	
525	    /// Prefill stats for the request's first shipped output. Built lazily so
526	    /// a `cached_tokens` fact arriving after `Scheduled` (chunked prefill
527	    /// reports it with the first chunk) still lands in the stats. Upstream
528	    /// invariant: computed + cached == prompt. `None` for a request that
529	    /// never reached `Scheduled`.
530	    fn take_prefill_stats(&mut self) -> Option<PrefillStats> {
531	        if self.prefill_stats_sent {
532	            return None;
533	        }
534	        let prompt_tokens = self.prompt_tokens?;
535	        self.prefill_stats_sent = true;
536	        Some(PrefillStats {
537	            num_prompt_tokens: prompt_tokens as u32,
538	            num_computed_tokens: prompt_tokens.saturating_sub(self.cached_tokens) as u32,
539	            num_cached_tokens: self.cached_tokens as u32,
540	            num_local_cached_tokens: self.cached_tokens as u32,
541	            num_external_cached_tokens: 0,
542	            num_cache_creation_tokens: 0,
543	        })
544	    }
545	}
