547	/// Translate one request's step record into at most one wire output. A
548	/// record carrying only metadata (scheduled, cached, kv-transfer) ships
549	/// nothing; its facts wait in `state` for the first real output. Returns
550	/// `(output, terminated)`.
551	fn reduce_update(
552	    state: &mut SteppedStream,
553	    update: RequestUpdate,
554	    anchor: &UnixAnchor,
555	) -> (Option<EngineCoreOutput>, bool) {
556	    if let Some(scheduled) = update.scheduled {
557	        state.first_token_events = Some(vec![
558	            EngineCoreEvent {
559	                r#type: EngineCoreEventType::Queued,
560	                timestamp: anchor.unix(scheduled.queued_at),
561	            },
562	            EngineCoreEvent {
563	                r#type: EngineCoreEventType::Scheduled,
564	                timestamp: anchor.unix(scheduled.scheduled_at),
565	            },
566	        ]);
567	        state.prompt_tokens = Some(scheduled.prompt_tokens);
568	    }
569	    if let Some(cached) = update.cached_tokens {
570	        state.cached_tokens = cached;
571	    }
572	    if let Some(params) = update.kv_transfer {
573	        state.kv_transfer_params = Some(params);
574	    }
575	    let prompt_logprobs = match update.prompt_echo.map(to_wire_prompt_logprobs).transpose() {
576	        Ok(payload) => payload.flatten(),
577	        Err(error) => return state.fail_prompt(&error),
578	    };
579	
580	    let mut token_ids = update.tokens;
581	    let mut has_logprobs = false;
582	    let mut positions: Vec<PositionLogprobs> = Vec::with_capacity(token_ids.len());
583	    for (i, &id) in token_ids.iter().enumerate() {
584	        let logprob = update.logprobs.get(i).cloned().flatten();
585	        if let Some(position) = to_wire_position_logprobs(id, logprob) {
586	            has_logprobs = true;
587	            positions.push(position);
588	        } else {
589	            positions.push(PositionLogprobs {
590	                entries: Vec::new(),
591	            });
592	        }
593	    }
594	
595	    let mut finish_reason: Option<EngineCoreFinishReason> = None;
596	    let mut stop_reason: Option<StopReason> = None;
597	    let mut terminated = false;
598	    match update.terminal {
599	        None => {}
600	        Some(Terminal::Finished {
601	            reason, stop_cause, ..
602	        }) => {
603	            if reason == FinishReason::Stop
604	                && stop_cause.is_none()
605	                && let Some(stop_sentinel_id) = state.stop_sentinel_id
606	            {
607	                token_ids.push(stop_sentinel_id);
608	                positions.push(PositionLogprobs {
609	                    entries: Vec::new(),
610	                });
611	            }
612	            if let Some(StopCause::Token(token_id)) = stop_cause {
613	                stop_reason = Some(StopReason::TokenId(token_id));
614	            }
615	
616	            finish_reason = Some(convert_finish_reason(reason));
617	            terminated = true;
618	        }
619	        Some(Terminal::Rejected { reason, .. }) => {
620	            // The vLLM wire only carries a string; typed classification stops
621	            // here and the rendered message is what reaches the client.
622	            let message = reason.to_string();
623	            warn!("request {} rejected: {message}", state.request_id);
624	            finish_reason = Some(EngineCoreFinishReason::Error);
625	            stop_reason = Some(StopReason::Text(message));
626	            terminated = true;
627	        }
628	        Some(Terminal::Failed { message, .. }) => {
629	            warn!("request {} failed: {message}", state.request_id);
630	            finish_reason = Some(EngineCoreFinishReason::Error);
631	            stop_reason = Some(StopReason::Text(message));
632	            terminated = true;
633	        }
634	    }
635	
636	    if token_ids.is_empty() && prompt_logprobs.is_none() && !terminated {
637	        return (None, false);
638	    }
639	
640	    let logprobs = has_logprobs.then_some(MaybeWireLogprobs::Direct(Logprobs { positions }));
641	    let mut output = engine_output(
642	        state.request_id.clone(),
643	        token_ids,
644	        logprobs,
645	        finish_reason,
646	        stop_reason,
647	        state.first_token_events.take(),
648	        state.take_prefill_stats(),
649	    );
650	    output.new_prompt_logprobs_tensors = prompt_logprobs;
651	    output.kv_transfer_params = state.kv_transfer_params.take().map(Box::new);
652	    (Some(output), terminated)
653	}
