655	/// Renders the contract's monotonic timestamps as wall-clock floats for the
656	/// vLLM wire. One anchor per bridge: both readings taken together at startup,
657	/// so every rendered timestamp shares one clock base.
658	struct UnixAnchor {
659	    sys: f64,
660	    instant: Instant,
661	}
662	
663	impl UnixAnchor {
664	    fn now() -> Self {
665	        Self {
666	            sys: now_secs_f64(),
667	            instant: Instant::now(),
668	        }
669	    }
670	
671	    fn unix(&self, t: Instant) -> f64 {
672	        if t >= self.instant {
673	            self.sys + (t - self.instant).as_secs_f64()
674	        } else {
675	            self.sys - (self.instant - t).as_secs_f64()
676	        }
677	    }
678	}
